{%- set s = pdf_extract_sections | default({}) -%}
{%- set summary_text = s.summary | default(s.text) | default("") -%}
<!doctype html>
<html lang="{{ target_locale | default('en-US') | e }}">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{{ s.headline | default("Jeroen van Bemmel — Systems Architect") | e }}</title>
  <style>
    :root {
      color-scheme: light;
      --ink: #142033;
      --muted: #5a6f86;
      --body: #31445c;
      --accent: #1f6feb;
      --rule: rgba(20, 32, 51, .14);
      --paper: #f7f4ef;
      --sans: "Segoe UI", system-ui, sans-serif;
      --serif: "Source Serif 4", "Iowan Old Style", "Palatino Linotype", Palatino, serif;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      padding: 2.25rem 1.5rem 2.5rem;
      font: 15px/1.5 var(--serif);
      color: var(--ink);
      background: var(--paper);
    }
    main { max-width: 42rem; margin: 0 auto; }
    .doc-header {
      margin: 0 0 1.35rem;
      padding-bottom: .9rem;
      border-bottom: 2px solid var(--ink);
    }
    .doc-kicker {
      margin: 0 0 .45rem;
      font: 650 .72rem/1.2 var(--sans);
      letter-spacing: .12em;
      text-transform: uppercase;
      color: var(--accent);
    }
    h1 {
      margin: 0;
      font: 700 1.85rem/1.15 var(--sans);
      letter-spacing: -.02em;
    }
    .extracted-on {
      margin: .55rem 0 0;
      font: 500 .88rem/1.35 var(--sans);
      color: var(--muted);
    }
    .extracted-on time { color: var(--ink); font-weight: 650; }
    .summary {
      margin: 0 0 .85rem;
      color: var(--body);
      text-wrap: pretty;
    }
    .summary:last-of-type { margin-bottom: 1.35rem; }
    h2 {
      margin: 1.55rem 0 .4rem;
      font: 700 .92rem/1.25 var(--sans);
      text-transform: uppercase;
      letter-spacing: .07em;
      color: var(--accent);
    }
    .section-note {
      margin: 0 0 .75rem;
      color: var(--muted);
      font: 400 .88rem/1.4 var(--sans);
    }
    .role {
      margin: 0 0 .95rem;
      padding-bottom: .85rem;
      border-bottom: 1px solid var(--rule);
      break-inside: avoid;
    }
    .role:last-child { margin-bottom: 0; border-bottom: 0; padding-bottom: 0; }
    .role-heading {
      display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      justify-content: space-between;
      gap: .25rem .85rem;
    }
    .role-title {
      font: 700 1.02rem/1.3 var(--sans);
      color: var(--ink);
    }
    .role-period {
      font: 600 .88rem/1.35 var(--sans);
      color: var(--muted);
      white-space: nowrap;
    }
    ul {
      margin: .4rem 0 0;
      padding-left: 1.15rem;
    }
    li {
      margin: .28rem 0;
      color: var(--body);
      text-wrap: pretty;
    }
    .timeline {
      margin: 0;
      padding: 0;
      list-style: none;
    }
    .timeline-item {
      display: grid;
      grid-template-columns: 7.75rem 1fr;
      gap: .35rem .85rem;
      margin: 0 0 1.05rem;
      padding: 0 0 .95rem;
      border-bottom: 1px solid var(--rule);
      break-inside: avoid;
    }
    .timeline-item:last-child {
      margin-bottom: 0;
      padding-bottom: 0;
      border-bottom: 0;
    }
    .timeline-period {
      color: var(--muted);
      font: 650 .86rem/1.4 var(--sans);
      white-space: nowrap;
    }
    .timeline-body { min-width: 0; }
    .timeline-org {
      font: 700 .98rem/1.3 var(--sans);
      color: var(--ink);
    }
    .timeline-title {
      color: var(--body);
      font: 600 .95rem/1.35 var(--sans);
    }
    .timeline-detail {
      margin-top: .1rem;
      color: var(--muted);
      font-size: .88em;
    }
    .timeline-description {
      margin: .4rem 0 0;
      color: var(--body);
      font-size: .95em;
      text-wrap: pretty;
    }
    .timeline-achievements {
      margin: .4rem 0 0;
      padding-left: 1.1rem;
    }
    .timeline-achievements li {
      margin: .22rem 0;
      color: var(--body);
      font-size: .93em;
    }
    .closing {
      margin: 1.5rem 0 0;
      color: var(--body);
      font-style: italic;
      text-wrap: pretty;
    }
    .footer {
      display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      justify-content: space-between;
      gap: .5rem 1rem;
      margin-top: 1.75rem;
      padding-top: .95rem;
      border-top: 1px solid var(--rule);
      font: 600 .92rem/1.35 var(--sans);
    }
    .footer a { color: var(--accent); text-decoration: none; }
    .footer a:hover { text-decoration: underline; }
    .footer-date {
      color: var(--muted);
      font-weight: 500;
    }
    @media print {
      body { padding: .7in .75in; background: #fff; }
      .role, .timeline-item, .footer { break-inside: avoid; }
      a { color: inherit; text-decoration: none; }
      .footer a::after { content: ""; }
    }
  </style>
</head>
<body>
  <main>
    <header class="doc-header">
      <p class="doc-kicker">Résumé extract</p>
      <h1>{{ s.headline | default("Jeroen van Bemmel — Systems Architect") | e }}</h1>
      <p class="extracted-on">Extracted <time data-extracted-on datetime="">—</time></p>
    </header>

    {% if summary_text %}
    {% for para in summary_text.split("\n\n") %}
    {% if para | trim %}
    <p class="summary">{{ para | trim | e }}</p>
    {% endif %}
    {% endfor %}
    {% endif %}

    {% if s.roles %}
    <h2>Selected relevant experience</h2>
    <p class="section-note">Emphasized for this conversation from the presentation evidence.</p>
    {% for role in s.roles %}
    <section class="role">
      <div class="role-heading">
        <div class="role-title">{{ role.title | e }}</div>
        {% if role.period %}<div class="role-period">{{ role.period | e }}</div>{% endif %}
      </div>
      {% if role.bullets %}
      <ul>
        {% for bullet in role.bullets %}
        <li>{{ bullet | e }}</li>
        {% endfor %}
      </ul>
      {% endif %}
    </section>
    {% endfor %}
    {% endif %}

    {% if career_timeline %}
    <h2>Career at a glance</h2>
    <p class="section-note">Complete employment chronology with role descriptions and key achievements — not filtered by this request.</p>
    <ul class="timeline">
      {% for entry in career_timeline %}
      <li class="timeline-item">
        <div class="timeline-period">{{ entry.period | e }}</div>
        <div class="timeline-body">
          <div class="timeline-org">{{ entry.organization | e }}</div>
          {% if entry.title %}<div class="timeline-title">{{ entry.title | e }}</div>{% endif %}
          {% if entry.detail %}<div class="timeline-detail">{{ entry.detail | e }}</div>{% endif %}
          {% if entry.description %}<p class="timeline-description">{{ entry.description | e }}</p>{% endif %}
          {% if entry.achievements %}
          <ul class="timeline-achievements">
            {% for achievement in entry.achievements %}
            <li>{{ achievement | e }}</li>
            {% endfor %}
          </ul>
          {% endif %}
        </div>
      </li>
      {% endfor %}
    </ul>
    {% endif %}

    {% if s.closing %}
    <p class="closing">{{ s.closing | e }}</p>
    {% endif %}

    <footer class="footer">
      <a href="{{ runtime.invite.url | e }}">View the interactive résumé</a>
      <span class="footer-date">Extracted <time data-extracted-on datetime="">—</time></span>
    </footer>
  </main>
  <script>
    (function () {
      var locale = {{ (target_locale | default("en-US")) | tojson }};
      var when = new Date();
      var iso = when.toISOString().slice(0, 10);
      var label = when.toLocaleDateString(locale, {
        year: "numeric",
        month: "long",
        day: "numeric"
      });
      document.querySelectorAll("[data-extracted-on]").forEach(function (el) {
        el.setAttribute("datetime", iso);
        el.textContent = label;
      });
    })();
  </script>
</body>
</html>

