```css
/* Shared positioning for the horizontal-split slide profile.
   Regions are fixed boxes (framework contract): they fill their allocation
   and clip. Media inside a region share that box.
   Column ratios come from the deck (`horizontal_split.left` / `.right`). */
.segment[data-layout="horizontal-split"] {
  min-height: 0;
  overflow: hidden;
}

.segment[data-layout="horizontal-split"] > .layout-container {
  height: 100%;
  min-height: 0;
  gap: 0.75rem;
}

.horizontal-split-left,
.horizontal-split-right {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.horizontal-split-image {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: flex-start;
  flex: 0 0 auto;
  gap: 0.5rem;
  min-width: 0;
  /* Fixed header media band so every slide keeps the same footprint. */
  height: 5.5rem;
}

.horizontal-split-image > :is(img, figure) {
  display: block;
  box-sizing: border-box;
  width: min(100%, 12rem);
  height: 5.5rem;
  margin: 0;
  object-fit: contain;
  object-position: right center;
}

.horizontal-split-image figure {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  gap: 0.25rem;
  overflow: hidden;
}

.horizontal-split-image figure img {
  display: block;
  width: 100%;
  height: 100%;
  margin: 0;
  object-fit: contain;
  object-position: right center;
}

.horizontal-split-image figcaption {
  font-size: 0.75rem;
  line-height: 1.3;
  color: var(--muted);
  text-align: right;
}

/* Evidence media share the right region's height evenly. */
.horizontal-split-right > :is(img, figure) {
  flex: 1 1 0;
  min-width: 0;
  min-height: 0;
  margin: 0;
  overflow: hidden;
}

.horizontal-split-right > img {
  display: block;
  width: 100%;
  object-fit: contain;
  object-position: top center;
}

.horizontal-split-right > figure {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.horizontal-split-right > figure > img {
  display: block;
  flex: 1 1 0;
  min-height: 0;
  width: 100%;
  height: 0;
  margin: 0;
  object-fit: contain;
  object-position: top center;
}

.horizontal-split-right figcaption {
  flex: 0 0 auto;
  font-size: 0.8rem;
  line-height: 1.35;
  color: var(--muted);
  text-align: center;
}

.horizontal-split-footer {
  color: var(--muted);
  font-size: 0.85rem;
}

/* Heading roles: h1 kicker, h2 title, h3 support */
.segment[data-layout="horizontal-split"] .horizontal-split-left > h1 {
  margin: 0;
  color: var(--accent);
  font-size: 0.72rem;
  font-weight: 750;
  letter-spacing: 0.14em;
  line-height: 1.3;
  text-transform: uppercase;
}

.segment[data-layout="horizontal-split"] .horizontal-split-left > h2 {
  margin: 0;
  color: var(--fg);
  font-size: clamp(1.85rem, 3.2vw, 2.55rem);
  font-weight: 750;
  letter-spacing: -0.03em;
  line-height: 1.08;
}

.segment[data-layout="horizontal-split"] .horizontal-split-left > h3 {
  margin: 0;
  color: var(--muted);
  font-size: 1.15rem;
  font-weight: 520;
  line-height: 1.35;
}
