#title {
  overflow: hidden;
  background:
    radial-gradient(circle at 92% 6%, rgba(43, 184, 200, 0.14), transparent 24%),
    radial-gradient(circle at 4% 96%, rgba(31, 111, 235, 0.10), transparent 28%),
    var(--bg);
}

#title > .layout-container {
  display: grid;
  grid-template-columns: minmax(2rem, 1fr) 9.5rem minmax(25rem, 31rem) 25rem;
  grid-template-rows: 1fr auto 1fr;
  gap: 0 1.6rem;
  min-height: 0;
}

#title .resume-title-image {
  grid-column: 2;
  grid-row: 2;
  align-self: center;
  width: 9rem;
  height: 11.5rem;
  overflow: hidden;
  border: 3px solid #fff;
  border-radius: 50%;
  background: #d7e2ef;
  box-shadow: 0 0.7rem 1.8rem rgba(24, 62, 108, 0.16);
}

#title .resume-title-image img {
  display: block;
  width: 100%;
  height: 100%;
  max-width: none;
  max-height: none;
  margin: 0;
  object-fit: cover;
  object-position: 50% 10%;
  transform: scale(1.28);
  transform-origin: 50% 18%;
}

#title .resume-title-left {
  grid-column: 3;
  grid-row: 2;
  align-self: center;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  min-width: 0;
}

#title h1 {
  margin: 0;
  color: var(--accent);
  font-size: 0.78rem;
  font-weight: 820;
  letter-spacing: 0.16em;
  line-height: 1.2;
  text-transform: uppercase;
}

#title h2 {
  margin: 0;
  color: var(--fg);
  font-size: clamp(2.7rem, 4.5vw, 3.4rem);
  font-weight: 780;
  letter-spacing: -0.05em;
  line-height: 0.98;
}

#title h2::after {
  content: "";
  display: block;
  width: 3.4rem;
  height: 0.2rem;
  margin-top: 0.55rem;
  border-radius: 1rem;
  background: linear-gradient(90deg, var(--accent), #2bb8c8);
}

#title h3 {
  max-width: 35ch;
  margin: 0;
  color: var(--muted);
  font-size: 1.22rem;
  font-weight: 520;
  line-height: 1.3;
}

#title .resume-title-left p {
  display: none;
}

#title .resume-title-right {
  grid-column: 4;
  grid-row: 3;
  align-self: end;
